import { defineConfig } from "vitest/config";
export default defineConfig({ test: { environment: "node", include: ["probe-criterion.test.ts"],
  testTimeout: 300_000, hookTimeout: 300_000, pool: "forks" } });
```

probe-criterion.test.ts:
```ts
import { appendFileSync, rmSync } from "node:fs";
import { expect, test } from "vitest";
import { SqliteEventStore } from "@moe/store";
import { spawnNode } from "./tests/e2e/control-room/daemon-children.js";
import { createLaneScratch, daemonEnv, seedEnv } from "./tests/e2e/control-room/daemon-ports.js";
import { readCriterionGoal } from "./apps/daemon/src/criterion-evidence/criterion-goal.js";
import { readCompiledContractBinding } from "./apps/daemon/src/planning/compiled-contract-binding.js";
import { activeCompiledGraphs } from "./apps/daemon/src/orchestrator/compiled-node-source.js";
import { readReleaseDossierInput } from "./apps/daemon/src/release/release-durable-facts.js";

const root = "D:/projexts/moe-next";
const OUT = `${root}/probe-out.txt`;
const say = (...a: unknown[]): void => { appendFileSync(OUT, `${a.map(String).join(" ")}\n`); };
const awaitExit = (c: any, ms: number): Promise<number | null> => new Promise((d) => {
  const t = setTimeout(() => d(null), ms); c.once("exit", (x: number | null) => { clearTimeout(t); d(x); });
});

test("PROBE: what the seeded fake-gh lane goal actually carries", async () => {
  const scratch = createLaneScratch(true);
  const kids: any[] = [];
  try {
    say("SCRATCH", scratch.root, scratch.projectId);
    const daemon = spawnNode([
      "--experimental-transform-types", `${root}/apps/daemon/src/daemon-main.ts`,
      `--dependencies=${root}/tests/e2e/control-room/fake-gh-dependencies.ts`,
      "--port=0", "--csrf-token=e2e-daemon-lane-csrf",
    ], root, { ...daemonEnv(scratch, "SPEED"), MOE_E2E_RELEASE_MODE: "SUCCESS",
      MOE_NODE_WORKSPACE: scratch.workspace });
    kids.push(daemon.child);
    const origin = await daemon.waitFor(/^listening on (\S+)$/mu, 90_000);
    say("ORIGIN", origin);
    const seed = spawnNode(["--experimental-transform-types",
      `${root}/apps/daemon/src/orchestrator/demo-seed-main.ts`], root,
      seedEnv(scratch, origin as string, "SPEED"));
    kids.push(seed.child);
    say("SEED EXIT", await awaitExit(seed.child, 180_000));
    say("SEED TAIL", seed.transcript().slice(-700));
    const store = SqliteEventStore.openForProject(scratch.storePath, scratch.projectId);
    const graphs = activeCompiledGraphs(store, scratch.projectId,
      new Set(["EXECUTION_ENABLED", "CLOSING", "COMPLETED"])) as any[];
    say("GRAPHS", JSON.stringify(graphs.map((g) => ({ goalRef: g.goalRef, run: g.planningRunRef }))));
    for (const g of graphs) {
      say("BINDING", g.goalRef, JSON.stringify(readCompiledContractBinding(store, scratch.projectId, g.planningRunRef)).slice(0, 240));
      say("CRITERION", g.goalRef, JSON.stringify(readCriterionGoal(store, scratch.projectId, g.goalRef)).slice(0, 240));
      say("DOSSIER", g.goalRef, readReleaseDossierInput(store, scratch.projectId, g.goalRef) === null ? "NULL" : "PRESENT");
    }
    store.close();
    expect(graphs.length).toBeGreaterThan(0);
  } finally {
    for (const c of kids) { try { c.kill(); } catch { /* teardown */ } }
    try { rmSync(scratch.root, { recursive: true, force: true }); } catch { /* teardown */ }
  }
});
```
NOTE ON READING IT BACK: vitest 4 swallowed `console.log` from inside the test on this host - the first run printed nothing and looked like a 2.6s no-op. The `appendFileSync` sink is why the output above exists. Anyone re-running this and seeing an empty terminal should `cat probe-out.txt`, not conclude the probe did nothing.
